import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.7nMnW4XS.js";const u=JSON.parse(`{"title":"PRD-024 · /science 'planets' tab — pair every PRD-023 lens annotation with a real article","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-024.md","filePath":"prd/PRD-024.md"}`),i={name:"prd/PRD-024.md"};function n(r,e,l,c,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="prd-024-·-science-planets-tab-—-pair-every-prd-023-lens-annotation-with-a-real-article" tabindex="-1">PRD-024 · /science &#39;planets&#39; tab — pair every PRD-023 lens annotation with a real article <a class="header-anchor" href="#prd-024-·-science-planets-tab-—-pair-every-prd-023-lens-annotation-with-a-real-article" aria-label="Permalink to &quot;PRD-024 · /science &#39;planets&#39; tab — pair every PRD-023 lens annotation with a real article&quot;">​</a></h1><blockquote><p>Status · Draft Date · 2026-06-03 Owner · Marko Closes into · GH issue #XXX (TBD), per-article slices, full-locale-coverage follow-up Builds on · PRD-023 (the visualisations) · ADR-017 (i18n overlay contract) · PRD-008 (/science editorial structure)</p></blockquote><blockquote><p><strong>Why this is a PRD.</strong> PRD-023 shipped ~10 new lens annotations + always-on overlays to /explore (Hill sphere · Lagrange points · magnetosphere · magnetic axis · sub-solar point · axial tilt + N/S compass · planetary stats · Earth comparison · active orbiters · natural satellites). Every other page in Orrery pairs every visual annotation with a <code>/science/{tab}/{section}</code> article the user can click through to — that&#39;s the design contract. /explore now has the annotations but most have no science article behind them. This PRD locks the structure + content plan to close the gap.</p></blockquote><h2 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h2><p>Create the <code>planets</code> tab under <code>/science</code> + add <code>hill-sphere</code> to the existing <code>orbits</code> tab. Author 8 articles total. Wire every PRD-023 lens panel link + WhyPopover trigger to its real URL.</p><p>The principle is the existing one from PRD-008: every annotation in the app links to a real /science article that explains the physics + cross-links to where else in the app that physics shows up.</p><h2 id="the-audit" tabindex="-1">The audit <a class="header-anchor" href="#the-audit" aria-label="Permalink to &quot;The audit&quot;">​</a></h2><p>What /explore has after PRD-023 vs what /science covers today:</p><table tabindex="0"><thead><tr><th>/explore feature (PRD-023)</th><th>Type</th><th>Needs <code>/science/...</code></th><th>Status</th></tr></thead><tbody><tr><td>Hill sphere wireframe</td><td>lens overlay (Slice B)</td><td><code>orbits/hill-sphere</code></td><td>❌ NEW</td></tr><tr><td>Lagrange L1/L2 markers</td><td>lens overlay (Slice B)</td><td><code>orbits/lagrange-points</code></td><td>✅ exists</td></tr><tr><td>Magnetosphere shell</td><td>lens overlay (Slice D)</td><td><code>planets/magnetic-fields</code></td><td>❌ NEW</td></tr><tr><td>Magnetic axis line</td><td>lens overlay (Slice E.3b)</td><td><code>planets/magnetic-fields</code></td><td>❌ NEW (shared with above)</td></tr><tr><td>Sub-solar point marker</td><td>lens overlay (Slice D)</td><td><code>planets/sub-solar-and-terminator</code></td><td>❌ NEW</td></tr><tr><td>Spin axis + N/S + rotation</td><td>always-on (Slice A.1 + E.3a)</td><td><code>planets/axial-tilt-and-seasons</code></td><td>❌ NEW</td></tr><tr><td>Tactical-scan stats overlay</td><td>lens overlay (Slice E.4)</td><td><code>planets/planetary-stats</code></td><td>❌ NEW</td></tr><tr><td>Earth comparison ghost</td><td>always-on (Slice E.2)</td><td><code>planets/planetary-stats</code> (shared)</td><td>❌ NEW</td></tr><tr><td>Active orbiter glyphs</td><td>always-on (Slice A.3)</td><td><code>planets/active-spacecraft-survey</code></td><td>❌ NEW</td></tr><tr><td>Natural satellite layer</td><td>always-on (#287 + PRD-023 Slice A)</td><td><code>planets/moons-of-the-system</code></td><td>❌ NEW</td></tr></tbody></table><p>Eight new articles to author. One section (Lagrange points) reuses an existing article.</p><h2 id="why-a-new-planets-tab-vs-cramming-into-existing-ones" tabindex="-1">Why a new &#39;planets&#39; tab vs cramming into existing ones <a class="header-anchor" href="#why-a-new-planets-tab-vs-cramming-into-existing-ones" aria-label="Permalink to &quot;Why a new &#39;planets&#39; tab vs cramming into existing ones&quot;">​</a></h2><p>Existing tabs:</p><ul><li><code>orbits</code> — orbital mechanics + special orbits. Hill sphere fits here (defined by orbital geometry).</li><li><code>scales-time</code> — units, frames, time scales (AU, light-minute, J2000). Stretching to fit planetary stats.</li><li><code>observation</code> — telescopes, deep space, galaxies. Wrong category for solar-system bodies.</li><li><code>mission-phases</code> — launch, EDL, transfers. Mission ops, not body science.</li></ul><p>Nothing covers <strong>planetary science as a field</strong> — body-level facts about each world (composition, atmosphere, fields, satellites, surface). That&#39;s a real gap PRD-023&#39;s visualisations now have surfaced.</p><p>A new <code>planets</code> tab is the honest fit.</p><h2 id="the-8-articles" tabindex="-1">The 8 articles <a class="header-anchor" href="#the-8-articles" aria-label="Permalink to &quot;The 8 articles&quot;">​</a></h2><h3 id="orbits-hill-sphere" tabindex="-1"><code>orbits/hill-sphere</code> <a class="header-anchor" href="#orbits-hill-sphere" aria-label="Permalink to &quot;`orbits/hill-sphere`&quot;">​</a></h3><p>Lead: &quot;The volume of space where a planet&#39;s gravity dominates over the Sun&#39;s pull.&quot;</p><p>Coverage: The Hill radius formula <code>r_H ≈ a (1-e) × (m / 3M)^(1/3)</code>. Why it scales with mass + distance. Real values for each planet (Earth 1.5M km / 236 R⊕; Jupiter 53M km / 744 R♃; Mercury only 220k km because it sits so close to the Sun&#39;s authority). Why Mercury&#39;s tiny Hill sphere matters for its moon-prospects (no stable orbit possible inside it). Link out to: SOI vs Hill sphere distinction · patched conics · Roche limit (the inner boundary equivalent).</p><h3 id="planets-axial-tilt-and-seasons" tabindex="-1"><code>planets/axial-tilt-and-seasons</code> <a class="header-anchor" href="#planets-axial-tilt-and-seasons" aria-label="Permalink to &quot;`planets/axial-tilt-and-seasons`&quot;">​</a></h3><p>Lead: &quot;Why Earth has seasons, why Uranus is rolled on its side, and why Venus rotates backward.&quot;</p><p>Coverage: Obliquity = angle between rotation axis and orbital plane normal. Earth 23.4° → seasons (sub-solar latitude oscillates ±23.4° over the year). Uranus 97.8° → axis lies in the orbital plane, so each pole gets 42 years of continuous sunlight followed by 42 years of darkness. Venus 177.4° → essentially upside-down + rotating backward (retrograde) at glacial 243-day pace. Likely formation stories: giant-impact theories for the outliers. Cross-link to: <code>magnetic-fields</code> (axis tilts compared); <code>sub-solar-and-terminator</code> (where the Sun lands when axis tilts).</p><h3 id="planets-magnetic-fields" tabindex="-1"><code>planets/magnetic-fields</code> <a class="header-anchor" href="#planets-magnetic-fields" aria-label="Permalink to &quot;`planets/magnetic-fields`&quot;">​</a></h3><p>Lead: &quot;Every planet&#39;s magnetosphere is different. Saturn&#39;s is uniquely aligned, Uranus&#39;s is chaotic, Venus and Mars don&#39;t have one at all.&quot;</p><p>Coverage: Dynamo basics — conducting fluid + rotation + thermal convection. Mercury&#39;s small but present field (oddity for such a small body). Earth&#39;s offset dipole drifting toward Siberia. Mars&#39;s lost dynamo (~4 Gyr ago) leaving only crustal anomalies. Jupiter&#39;s planet-system-spanning magnetotail. Saturn&#39;s near-perfect axial alignment (the unsolved mystery — no other dynamo we know aligns this cleanly). Uranus + Neptune&#39;s wildly off-axis + centre-offset dipoles, suggesting their dynamos sit in a different conducting layer (probably the ionic-water mantle, not the deep core). The Van Allen analogues: every planet with a field has trapped radiation belts.</p><h3 id="planets-moons-of-the-system" tabindex="-1"><code>planets/moons-of-the-system</code> <a class="header-anchor" href="#planets-moons-of-the-system" aria-label="Permalink to &quot;`planets/moons-of-the-system`&quot;">​</a></h3><p>Lead: &quot;Galileo&#39;s four-night observation in 1610 ended geocentrism. The system&#39;s moons are still ending old assumptions today.&quot;</p><p>Coverage: The Galilean moons — Io&#39;s volcanism, Europa&#39;s subsurface ocean, Ganymede&#39;s magnetic field + size record, Callisto&#39;s ancient crater fields. Saturn&#39;s Titan (thicker atmosphere than Mars!) + Enceladus (south-pole tiger stripes vent water + organics). Mars&#39;s Phobos + Deimos (captured asteroids, Phobos on a death spiral toward Mars). Neptune&#39;s Triton (retrograde, captured, geyser activity). Pluto&#39;s Charon (mutual barycentre outside Pluto&#39;s body). Why so many moons cluster around the gas giants. Cross-link to /missions for the missions that imaged each.</p><h3 id="planets-active-spacecraft-survey" tabindex="-1"><code>planets/active-spacecraft-survey</code> <a class="header-anchor" href="#planets-active-spacecraft-survey" aria-label="Permalink to &quot;`planets/active-spacecraft-survey`&quot;">​</a></h3><p>Lead: &quot;What&#39;s at each planet right now: from MRO at Mars to Juno at Jupiter to Akatsuki at Venus.&quot;</p><p>Coverage: One paragraph per body, listing active orbiters + their agencies + their dates of arrival + what they&#39;re studying. The active-orbiter glyphs on /explore link here, and entries here cross-link to <code>/fleet/orbiter/{id}</code> for the mission card. Includes the &quot;global space programs&quot; framing — UAE Hope, JAXA Akatsuki, ISRO Mangalyaan, CNSA Tianwen-1 explicitly called out, not just the NASA contingent. Notes on past missions (Cassini at Saturn, Voyagers at the outer planets, MESSENGER at Mercury) for context.</p><h3 id="planets-planetary-stats" tabindex="-1"><code>planets/planetary-stats</code> <a class="header-anchor" href="#planets-planetary-stats" aria-label="Permalink to &quot;`planets/planetary-stats`&quot;">​</a></h3><p>Lead: &quot;How different is Jupiter from Earth, really? Eleven times the diameter. Two and a half times the surface gravity. 100,000 times the atmosphere at 1 bar.&quot;</p><p>Coverage: Comparison tables — diameter (in km and Earth-relative), surface gravity (in g), atmospheric pressure (in bar), rotation period, day length (sidereal vs solar). Why surface gravity isn&#39;t predictable from mass alone (Mars is half Earth&#39;s mass but only 38% gravity because radius matters more than mass for a given density). Why &quot;atmospheric pressure at the surface&quot; is a fuzzy concept for gas giants (we use the 1-bar level). Day-length surprises: Venus&#39;s day longer than its year. Cross-link to PRD-023 Slice E.4&#39;s tactical-scan overlay + Slice E.2&#39;s Earth-comparison ghost.</p><h3 id="planets-sub-solar-and-terminator" tabindex="-1"><code>planets/sub-solar-and-terminator</code> <a class="header-anchor" href="#planets-sub-solar-and-terminator" aria-label="Permalink to &quot;`planets/sub-solar-and-terminator`&quot;">​</a></h3><p>Lead: &quot;Where it&#39;s noon on a planet right now, and the line between day and night.&quot;</p><p>Coverage: Sub-solar point = the longitude directly under the Sun at this instant. Terminator = the great circle 90° from the sub-solar point, marking the boundary between lit and unlit hemispheres. How both shift with the planet&#39;s rotation + season + orbital position. Why the terminator is a sharp line on airless bodies (Mercury, Moon) but a gradient on bodies with atmospheres (Earth, Venus). The &quot;twilight zone&quot; — historically the most interesting place to observe surface detail because of the long shadows. Cross-link to <code>axial-tilt-and-seasons</code> (the sub-solar latitude oscillates with the season).</p><h3 id="planets-intro-tab-level-lead-in" tabindex="-1"><code>planets/_intro</code> (tab-level lead-in) <a class="header-anchor" href="#planets-intro-tab-level-lead-in" aria-label="Permalink to &quot;`planets/_intro` (tab-level lead-in)&quot;">​</a></h3><p>The <code>_intro.json</code> file every tab has — sets the tab&#39;s overall framing. Plan: 2-3 paragraphs introducing planetary science as a field, what the tab covers, and the cross-app pattern (every section&#39;s annotation lives somewhere in /explore + /fleet).</p><h2 id="lens-link-wiring" tabindex="-1">Lens link wiring <a class="header-anchor" href="#lens-link-wiring" aria-label="Permalink to &quot;Lens link wiring&quot;">​</a></h2><p>Each PRD-023 layer key gets paired with its science URL. Implementation pattern is already in place — <code>lens-story-link.svelte</code> + <code>WhyPopover</code> both take <code>tab</code> + <code>section</code> props that emit a <code>/science/{tab}/{section}</code> link. No new component work; just need to fill in the right props.</p><p>Concretely:</p><ul><li><code>hill-sphere</code> lens layer → <code>tab: &#39;orbits&#39;, section: &#39;hill-sphere&#39;</code></li><li><code>lagrange-points</code> lens layer → <code>tab: &#39;orbits&#39;, section: &#39;lagrange-points&#39;</code> (already exists)</li><li><code>magnetosphere</code> + magnetic axis → <code>tab: &#39;planets&#39;, section: &#39;magnetic-fields&#39;</code></li><li><code>sub-solar</code> lens layer → <code>tab: &#39;planets&#39;, section: &#39;sub-solar-and-terminator&#39;</code></li><li><code>planet-stats</code> lens layer → <code>tab: &#39;planets&#39;, section: &#39;planetary-stats&#39;</code></li><li>N/S badges + spin axis (always-on, no lens key but linked from WhyPopover) → <code>tab: &#39;planets&#39;, section: &#39;axial-tilt-and-seasons&#39;</code></li></ul><h2 id="locale-coverage" tabindex="-1">Locale coverage <a class="header-anchor" href="#locale-coverage" aria-label="Permalink to &quot;Locale coverage&quot;">​</a></h2><p>ADR-017&#39;s contract is &quot;every locale-overlay file exists or the loader falls back to en-US&quot;. The fallback in <code>src/lib/data.ts:128-145</code> for planets confirms — missing locale overlays silently fall through to en-US.</p><p><strong>This PRD&#39;s Slice 1 ships en-US only.</strong> All 8 articles + the <code>_intro.json</code> author full editorial content in English. Other 13 locales get TODO placeholder files OR are skipped (loader falls back).</p><p><strong>Locale propagation lands as Slice 2 + follow-up.</strong> Either via the existing wave23 tooling (re-usable for science articles?) or a fresh tsx script that calls the Anthropic API to translate each locale (8 × 13 = 104 calls, batchable). Tracked separately to keep Slice 1&#39;s editorial work focused.</p><h2 id="slice-order" tabindex="-1">Slice order <a class="header-anchor" href="#slice-order" aria-label="Permalink to &quot;Slice order&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Slice 1 — PRD + &#39;planets&#39; tab structure + 8 en-US articles + lens link wiring</span></span>\n<span class="line"><span>Slice 2 — i18n propagation to the other 13 locales</span></span>\n<span class="line"><span>Slice 3 — diagrams (each article gets at least one SVG schematic where helpful)</span></span>\n<span class="line"><span>Slice 4 — cross-link wiring: each article&#39;s &quot;see in app&quot; entries point to live /explore + /fleet routes; bidirectional polish</span></span></code></pre></div><p>Slice 1 is the bulk of editorial work and ships in this session. Slices 2-4 are follow-ups.</p><h2 id="done-definition-slice-1" tabindex="-1">Done definition (Slice 1) <a class="header-anchor" href="#done-definition-slice-1" aria-label="Permalink to &quot;Done definition (Slice 1)&quot;">​</a></h2><ul><li>8 new articles author full en-US content (intro + narrative_101 + body_paragraphs + diagram_caption)</li><li><code>planets/_index.json</code> registers the tab + section order</li><li><code>planets/_intro.json</code> provides the tab-level lead-in (en-US)</li><li>Every PRD-023 lens link + WhyPopover trigger resolves to a real <code>/science/...</code> URL (not 404)</li><li><code>validate-data</code> green</li><li>Memory <code>project_science_translation_pipeline</code> updated if the wave23 tooling can be reused</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Actual diagrams (Slice 3 — articles ship without <code>diagram</code> keys initially; can launch with the text-only narrative)</li><li>Audio episodes pairing each article — separate pipeline (PRD-016)</li><li>Cross-links from articles back to /fleet for the spacecraft survey — Slice 4</li><li>Re-organising <code>scales-time</code> or <code>observation</code> tabs (out of scope; the new tab adds without rearranging)</li></ul>',54)])])}const b=t(i,[["render",n]]);export{u as __pageData,b as default};
